data.query:
query Query(
  $d: WorkOrderProcessDistributionWhereInput,
  $g: WorkOrderProcessDistributionGroupWhereInput
) {
  d:workOrderProcessDistribution(where: $d) {
    edges {
      node {
        id
        workcenterId
        distributionGroupId
        balanceQuantity
        requiredQuantity
        workOrder {id number}
        workcenterId
        earliestStartAt
        estimatedTime
        latestStartAt
        workOrderProcess {
          id
          productStrategyProcessId 
        }
      }
    }
  }
  g: workOrderProcessDistributionGroup(where: $g) {
    edges {
      node {
        id
        workOrderProcessDistributionStatusId
        balanceQuantity
        requiredQuantity
        estimatedTime
        workcenterId
        distributions {
          edges {
            node {
              id
              requiredQuantity
              workOrderProcess {
                productStrategyProcessId
              }
              estimatedTime
              earliestStartAt
              latestStartAt
              workOrderProcessDistributionStatusId

            }
          }
        }
      }
    }
  }
}

data.transform:
(
  $g := g.edges.node;
  $d := d.edges.node;

  {
    "dg": $g.{
      "update": {
        "balanceQuantity": balanceQuantity + $d.balanceQuantity,
        "requiredQuantity": requiredQuantity + $d.requiredQuantity,
        "estimatedTime": estimatedTime + $d.estimatedTime
      },
      "where": {
        "id": id
      }
    },

    "du": $d.{
      "update": {
        "distributionGroupId": $g.id
      },
      "where": {
        "id":id
      }
    }
  }


)

(
  $g := g.edges.node;
  $d := d.edges.node;
  $id := $state.context.REQUEST.DATA.id;
  $dgid := $cuid();

  {
    "dg":  $g.{
      "update": {
        "balanceQuantity": balanceQuantity - $d.balanceQuantity,
        "requiredQuantity": requiredQuantity - $d.requiredQuantity,
        "estimatedTime": estimatedTime - $d.estimatedTime
      },
      "where": {
        "id": id
      }
    } ,

    "du": $d.{
      "update": {
        "distributionGroupId": $dgid
      },
      "where": {
        "id":id
      }
    },


    "dc": {
      "create": $merge([$omit($d,["id","workOrder","workOrderProcess","distributionGroupId"]),{"id":$dgid}])
    }
  }


)

